/// <summary>
/// Extension of class <c>PurchPurchaseOrderController</c>
/// </summary>
[ExtensionOf(classStr(PurchPurchaseOrderController))]
final class PurchPurchaseOrderController_Extension
{
}

Method.Source:
    /// <summary>
    /// Gets the title for the <c>PurchPurchaseOrder</c> report.
    /// </summary>
    /// <returns>
    /// The <c>PurchPurchaseOrder</c> title.
    /// </returns>
    protected str documentTitle()
    {
        str     documentTitle = next documentTitle();
        
        if (documentTitle ==  literalStr("@GLS180099"))
        {
            documentTitle =  literalStr("@SYS25545");
        }

        return documentTitle;
    }
